mapper.select:
/* com.biz.framework.mapper.pages.RefundItemMapper.findRefundItems */ SELECT REFUND_ITEM_ID , REFUND_ITEM_NAME , USE_IND , SE06.CODE_NAME AS USE_IND_NAME FROM TB_REFUNDITEM RI LEFT JOIN CDBASE SE06 ON SE06.CO_CODE = RI.CO_CODE AND SE06.PATTERN_CODE = 'SE06' AND SE06.BASE_CODE = RI.USE_IND WHERE 1=1 AND RI.CO_CODE = #{loginCoId}
AND REFUND_ITEM_ID LIKE CONCAT('%', #{searchId}, '%')
AND REFUND_ITEM_NAME LIKE CONCAT('%', #{searchName}, '%')
AND USE_IND = #{searchUseInd}

mapper.insert:
/* com.biz.framework.mapper.pages.RefundItemMapper.saveRefundItem */

    SELECT CONCAT('RI-', LPAD(IFNULL(MAX(cast(SUBSTRING_INDEX(REFUND_ITEM_ID , '-', -1) AS UNSIGNED INTEGER)), 0) + 1, 4, '0'))
    FROM TB_REFUNDITEM
    WHERE CO_CODE      = #{loginCoId}

INSERT INTO TB_REFUNDITEM
(
    CO_CODE
    , REFUND_ITEM_ID
    , REFUND_ITEM_NAME
    , USE_IND
) VALUES
(
    #{loginCoId}
    , #{refundItemId}
    , #{refundItemName}
    , #{useInd}
)

mapper.update:
/* com.biz.framework.mapper.pages.ApplypaymentMapper.updateRefundItem */
UPDATE TB_REFUNDITEM
   SET REFUND_ITEM_NAME     = #{refundItemName}
     , USE_IND              = #{useInd}
 WHERE CO_CODE              = #{loginCoId}
   AND REFUND_ITEM_ID       = #{refundItemId}

mapper.delete:
/* com.biz.framework.mapper.pages.ApplypaymentMapper.deleteRefundItem */
DELETE FROM TB_REFUNDITEM
 WHERE CO_CODE          = #{loginCoId}
   AND REFUND_ITEM_ID   = #{refundItemId}
